/**
 * Input (issue #12) — text entry over the semantic roles.
 *
 * shadcn-compatible API, Augur-owned styling: a native `<input>` styled
 * exclusively through the semantic role custom properties delivered by
 * `@augur/design-system/styles.css` (see `./input.css`). React 19
 * style: a plain function component; `ref` forwards through props (no
 * forwardRef).
 *
 * Contracts (consumer view: docs "Input" page; decision record:
 * `docs/components.md` in this package):
 *
 *   - Input is independent of FormField: it never imports from the
 *     form-field tree and works with any consumer-provided labeling
 *     (`<label htmlFor>`). The FormField pattern (issue #12) composes
 *     this component; the dependency points one way only.
 *   - Invalid (`invalid`): sets `aria-invalid="true"` and paints the
 *     danger-role border. The brand defines no danger hue (theme
 *     decision D1), so the error MESSAGE text — not the border color —
 *     carries the meaning; never color alone.
 *   - Disabled: native `disabled`, reduced-contrast value, `cursor:
 *     not-allowed` (the FD-06 Proposed treatment, same as Button).
 *   - Read-only: native `readOnly`. Deliberately NOT styled like
 *     disabled: the field stays focusable and its value selectable and
 *     copyable; a quiet surface signals "displayed, not edited".
 *   - Keyboard focus needs no CSS here: the theme contract's shared
 *     `:focus-visible` rule (2px ring, 2px offset, `--ring` color)
 *     applies to every element, including this one.
 *
 * Controlled and uncontrolled usage are both plain React: `value`/
 * `onChange` or `defaultValue` — the component adds no state and no
 * validation; validation ownership stays with the consumer (see the
 * docs page; FormField is the wiring pattern, not a form framework).
 */

import "./input.css";
import type { ComponentProps } from "react";
import { cx } from "@/lib/utils";

export type InputProps = ComponentProps<"input"> & {
  /**
   * Invalid state: `aria-invalid="true"` plus the danger-role border.
   * Pair with a visible error message announced to assistive
   * technology (FormField wires one automatically; standalone usage
   * wires `aria-describedby` by hand).
   */
  invalid?: boolean;
};

export function Input({ invalid = false, className, ...props }: InputProps) {
  return (
    <input
      {...props}
      aria-invalid={invalid || undefined}
      className={cx("aug-input", "augur-type-ui", className)}
    />
  );
}

/*
 * Input styles (issue #12).
 *
 * Color: ONLY semantic role custom properties from ../../styles/theme.css
 * (which references generated tokens). No raw color values, no new
 * custom properties.
 *
 * Geometry: FD-01 spacing and FD-03 radius consume the encoded tokens
 * (--augur-spacing-*, --augur-rounded-control — issues #45/#51), the
 * same pattern Button and Card use. FD-03 names `radius.control`
 * explicitly for inputs; FD-02 control heights remain the adopted
 * structural constants. The decision record for this slice lives in
 * ../../docs/components.md.
 */

.aug-input {
  box-sizing: border-box;
  display: block;
  width: 100%;
  height: 36px; /* FD-02 control.height.md (adopted) */
  padding: 0 var(--augur-spacing-md); /* FD-01 control padding (encoded); text fields read
                     better a step tighter than the md button's 16px */
  margin: 0;
  border: 1px solid var(--input);
  border-radius: var(--augur-rounded-control); /* FD-03 radius.control (encoded: 0px) */
  background-color: transparent; /* sits on any surface: canvas or card */
  color: var(--foreground);
  vertical-align: middle;
}

.aug-input::placeholder {
  color: var(--muted-foreground);
  opacity: 1; /* the UA default dimming would stack with the role color;
                  a hint in the secondary voice, never required information */
}

/*
 * Invalid: the danger-role border (aria-invalid is set by the
 * component's `invalid` prop). The theme defines no danger hue
 * (theme decision D1) — the visible error message text carries the
 * meaning; the border is reinforcement, never the sole signal.
 */
.aug-input[aria-invalid="true"] {
  border-color: var(--destructive);
}

/*
 * Read-only: still focusable, value selectable and copyable —
 * deliberately NOT the disabled treatment. The quiet surface signals
 * "displayed, not edited" while the text stays in the secondary-text
 * contrast pairing.
 */
.aug-input[readonly] {
  background-color: var(--muted);
  cursor: default;
}

/*
 * Disabled (FD-06 Proposed treatment, same contract as Button
 * decision D5): non-interactive via the native attribute,
 * reduced-contrast value that remains present in the DOM.
 * WCAG 1.4.3 exempts disabled controls from contrast minimums.
 */
.aug-input:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

/* Keyboard focus: painted by the theme contract's shared
   :focus-visible rule (2px ring, 2px offset, --ring); no per-component
   focus CSS, exactly like Button. */

/* FD-02 adopted touch target minimum; desktop size variants remain intact. */
@media (pointer: coarse) {
  .aug-input { min-height: 44px; min-width: 44px; }
}
